import shutil
import re
import openpyxl
from datetime import datetime, date
from openpyxl.utils.datetime import from_excel

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

DATE_FORMATS = (
    "%Y/%m/%d",
    "%Y-%m-%d",
    "%Y/%m/%d %H:%M:%S",
    "%Y-%m-%d %H:%M:%S",
    "%Y/%m/%d %H:%M",
    "%Y-%m-%d %H:%M",
    "%m/%d/%Y",
    "%d/%m/%Y",
    "%m/%d/%Y %H:%M:%S",
    "%d/%m/%Y %H:%M:%S",
    "%m/%d/%Y %H:%M",
    "%d/%m/%Y %H:%M",
)

def is_blank(v):
    return v is None or (isinstance(v, str) and v.strip() == "")

def is_date_format(fmt):
    if not fmt or fmt == "General":
        return False
    return any(ch in fmt for ch in "ymd")

def normalize(v, fmt=None):
    if v is None:
        return None

    if isinstance(v, str):
        s = v.strip()
        if s == "":
            return None

        for f in DATE_FORMATS:
            try:
                return datetime.strptime(s, f)
            except ValueError:
                pass

        num = s.replace(",", "")
        if re.fullmatch(r"[+-]?\d+", num):
            try:
                return int(num)
            except Exception:
                pass
        if re.fullmatch(r"[+-]?(\d+\.\d*|\.\d+)([eE][+-]?\d+)?", num):
            try:
                return float(num)
            except Exception:
                pass

        return s

    if isinstance(v, bool):
        return v

    if isinstance(v, (int, float)) and is_date_format(fmt):
        try:
            return from_excel(v)
        except Exception:
            return v

    if isinstance(v, date) and not isinstance(v, datetime):
        return datetime(v.year, v.month, v.day)

    return v

# The workbook/data region is A1:I7.
max_row = 7
delete_rows = set()

for r in range(1, max_row + 1):
    h_val = vws.cell(row=r, column=8).value
    i_val = vws.cell(row=r, column=9).value
    if not is_blank(i_val) and is_blank(h_val):
        delete_rows.add(r)

kept_rows = [r for r in range(1, max_row + 1) if r not in delete_rows]

for out_r in range(1, max_row + 1):
    if out_r <= len(kept_rows):
        src_r = kept_rows[out_r - 1]
        for c in range(1, 10):
            src_cell = vws.cell(row=src_r, column=c)
            ws.cell(row=out_r, column=c).value = normalize(src_cell.value, src_cell.number_format)
    else:
        for c in range(1, 10):
            ws.cell(row=out_r, column=c).value = None

print("Deleted rows:", sorted(delete_rows))
print("Kept rows:", kept_rows)
for r in range(1, max_row + 1):
    print(r, [ws.cell(row=r, column=c).value for c in (1, 8, 9)])

wb.save(OUT)
